# Returns item identifiers and labels for cultural POIs with coordinates (p625).
SELECT ?item ?itemLabel ?coord ?coordValue
WHERE {
  ?item wdt:P17 wd:Q29 ;
        wdt:P127 wd:Q11959 ;
        p625 ?coord.
  ?coord psv:P625 ?coordValue.
