    EXISTS { ?item wdt:P31/wdt:P279* wd:Q153042 }
  )
  SERVICE bd:ServiceParam { bd:serviceParam bd:service.sparql "true" }
  {
    ?item rdfs:label ?itemLabel.
    FILTER (LANG(?itemLabel) = "en" || LANG(?itemLabel) = "es")
  }
}
